#!/usr/bin/env bash
set -euo pipefail
[[ -d .git && -f pubspec.yaml && -f desktop/hyper_player/VISUAL_ALIGNMENT_9.md ]] || { echo 'Run in the repository root after visual update 9.' >&2; exit 1; }
python3 - <<'PARITY_CORRECTION'
from pathlib import Path
import base64
files = {
'desktop/hyper_player/lib/main.dart': '',
'desktop/hyper_player/lib/local_thumbnail.dart': '',
'desktop/hyper_player/lib/screens/search_screen.dart': '',
'desktop/hyper_player/lib/screens/info_sheets.dart': '',
'desktop/hyper_player/lib/screens/about_android.dart': '',
'desktop/hyper_player/test/parity_correction_test.dart': '',
'desktop/hyper_player/test/statistics_sheets_test.dart': '',
'desktop/hyper_player/PARITY_CORRECTION_1.md': '',
}
for name, data in files.items():
    p = Path(name)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(data))
print('Partial parity correction installed. Rebuild Windows and verify thumbnails on laptop.')
PARITY_CORRECTION
